import ir.reyden.reydesk.companion.NotificationPrivacy
import ir.reyden.reydesk.settings.StreamPreferences
import ir.reyden.reydesk.companion.FileTransferPolicy

fun main() {
    var passed = 0
    fun checkCase(name: String, value: Boolean) { check(value) { name }; passed++ }
    fun redact(previews: Boolean = true, pkg: String = "com.example.chat", category: String = "msg", title: String = "Hello", body: String = "Lunch tomorrow?") = NotificationPrivacy.redact(previews, pkg, category, title, body)
    checkCase("previews off by default protect ordinary message", redact(previews = false))
    checkCase("ordinary opted-in content remains readable while locked", !redact() && !NotificationPrivacy.allowsActions(locked = true, redacted = false))
    checkCase("previews off hides content while locked", redact(previews = false) && !NotificationPrivacy.allowsActions(locked = true, redacted = true))
    checkCase("bank content hidden while locked", redact(pkg = "com.example.bankapp") && !NotificationPrivacy.allowsActions(locked = true, redacted = true))
    checkCase("OTP content hidden while locked", redact(body = "Use 567890 to sign in") && !NotificationPrivacy.allowsActions(locked = true, redacted = true))
    checkCase("unlocked ordinary content permits actions", NotificationPrivacy.allowsActions(locked = false, redacted = false))
    checkCase("unlocked hidden content has no actions", !NotificationPrivacy.allowsActions(locked = false, redacted = true))
    checkCase("ordinary opted-in content allowed", !redact())
    checkCase("app-secret notification stays hidden with previews enabled", NotificationPrivacy.redact(true, "com.example.chat", "msg", "Hello", "Lunch tomorrow?", systemHidden = true))
    checkCase("bank package always hidden", redact(pkg = "com.example.bankapp"))
    checkCase("wallet app always hidden", redact(pkg = "com.example.wallet"))
    checkCase("authenticator app always hidden", redact(pkg = "com.example.authenticator"))
    checkCase("security title always hidden", redact(title = "Security alert"))
    checkCase("OTP body always hidden", redact(body = "Your OTP is ready"))
    checkCase("numeric verification hidden", redact(body = "Use 567890 to sign in"))
    checkCase("persian code hidden", redact(body = "۱۲۳۴۵۶"))
    checkCase("arabic code hidden", redact(body = "١٢٣٤٥٦"))
    checkCase("persian bank hidden", redact(title = "پیام بانک"))
    checkCase("persian password hidden", redact(body = "رمز ورود شما"))
    checkCase("payment hidden", redact(body = "Payment completed"))
    checkCase("password hidden", redact(body = "Reset your password"))
    checkCase("choice-only valid choice", NotificationPrivacy.acceptsReply("Yes", false, listOf("Yes", "No")))
    checkCase("choice-only arbitrary reply denied", !NotificationPrivacy.acceptsReply("Maybe", false, listOf("Yes", "No")))
    checkCase("freeform valid reply", NotificationPrivacy.acceptsReply("Hello", true, emptyList()))
    checkCase("blank reply denied", !NotificationPrivacy.acceptsReply(" ", true, emptyList()))
    checkCase("oversized reply denied", !NotificationPrivacy.acceptsReply("x".repeat(2001), true, emptyList()))
    checkCase("maximum reply accepted", NotificationPrivacy.acceptsReply("x".repeat(2000), true, emptyList()))
    checkCase("no input capability denied", !NotificationPrivacy.acceptsReply("Hello", false, emptyList()))
    checkCase("migrated preferences stay Custom host default", StreamPreferences.normalized(0, 0, 0).preset == "Custom")
    checkCase("invalid preset stays Custom", StreamPreferences.normalized(1080, 60, 12000, "Unknown").preset == "Custom")
    checkCase("Performance settings", StreamPreferences.forPreset("Performance") == StreamPreferences(720, 30, 4000, "Performance"))
    checkCase("Balanced settings", StreamPreferences.forPreset("Balanced") == StreamPreferences(1080, 30, 8000, "Balanced"))
    checkCase("Quality settings", StreamPreferences.forPreset("Quality") == StreamPreferences(1080, 60, 12000, "Quality"))
    checkCase("Auto uses accepted initial profile", StreamPreferences.forPreset("Auto") == StreamPreferences(1080, 60, 12000, "Auto"))
    checkCase("normalization preserves explicit preset", StreamPreferences.normalized(720, 30, 4000, "Performance").preset == "Performance")
    checkCase("unknown preset falls back safely", StreamPreferences.forPreset("Bogus") == StreamPreferences())
    checkCase("duplicate filename suffix precedes extension", FileTransferPolicy.uniqueName("existing.txt", 1) == "existing (1).txt")
    checkCase("hidden filename suffix preserves dot name", FileTransferPolicy.uniqueName(".hidden", 2) == ".hidden (2)")
    checkCase("Unicode filename suffix preserves extension", FileTransferPolicy.uniqueName("گزارش.pdf", 3) == "گزارش (3).pdf")
    val hash = "a".repeat(64)
    checkCase("valid bounded file offer", FileTransferPolicy.validOffer("abc", "گزارش.pdf", 100, hash))
    checkCase("zero-byte file allowed", FileTransferPolicy.validOffer("abc", "empty.txt", 0, hash))
    checkCase("maximum file allowed", FileTransferPolicy.validOffer("abc", "file.bin", FileTransferPolicy.maximumBytes, hash))
    checkCase("oversized file rejected", !FileTransferPolicy.validOffer("abc", "file.bin", FileTransferPolicy.maximumBytes + 1, hash))
    checkCase("unsigned size overflow rejected", !FileTransferPolicy.validOffer("abc", "file.bin", -1, hash))
    checkCase("invalid digest rejected", !FileTransferPolicy.validOffer("abc", "file.bin", 100, "g".repeat(64)))
    checkCase("short digest rejected", !FileTransferPolicy.validOffer("abc", "file.bin", 100, "a"))
    checkCase("traversal display name rejected", !FileTransferPolicy.safeName("../bad.exe"))
    checkCase("Windows path name rejected", !FileTransferPolicy.safeName("C:\\bad.exe"))
    checkCase("control display name rejected", !FileTransferPolicy.safeName("bad\n.txt"))
    checkCase("dot display name rejected", !FileTransferPolicy.safeName(".."))
    checkCase("exact chunk allowed", FileTransferPolicy.validChunk(0, 0, 16384, 20000, false))
    checkCase("out-of-order chunk rejected", !FileTransferPolicy.validChunk(16384, 0, 16384, 40000, false))
    checkCase("oversized chunk rejected", !FileTransferPolicy.validChunk(0, 0, 16385, 20000, false))
    checkCase("past-end chunk rejected", !FileTransferPolicy.validChunk(10, 10, 100, 50, true))
    checkCase("premature final rejected", !FileTransferPolicy.validChunk(0, 0, 10, 50, true))
    checkCase("missing final rejected", !FileTransferPolicy.validChunk(0, 0, 50, 50, false))
    checkCase("empty-file final accepted", FileTransferPolicy.validChunk(0, 0, 0, 0, true))
    checkCase("empty intermediate rejected", !FileTransferPolicy.validChunk(0, 0, 0, 50, false))
    checkCase("signed offset overflow rejected", !FileTransferPolicy.validChunk(-1, 0, 10, 50, false))
    checkCase("diagnostic ordinary reason", NotificationPrivacy.reason(true, "ir.nasim Bale", "msg", "Chat", "سلام تست ری‌دسک") == null)
    checkCase("diagnostic owner preview reason", NotificationPrivacy.reason(false, "chat", "msg", "Hi", "Hi") == "previews_off")
    checkCase("diagnostic secret reason", NotificationPrivacy.reason(true, "chat", "msg", "Hi", "Hi", true) == "system_secret")
    checkCase("diagnostic sensitive reason", NotificationPrivacy.reason(true, "chat", "msg", "Hi", "پرداخت") == "sensitive_term")
    checkCase("diagnostic numeric reason", NotificationPrivacy.reason(true, "chat", "msg", "Hi", "567890") == "numeric_code")
    checkCase("opt-in shows codes", NotificationPrivacy.reason(true, "chat", "msg", "Hi", "567890", allowSensitive = true) == null)
    checkCase("opt-in shows bank text", NotificationPrivacy.reason(true, "chat", "msg", "Hi", "پرداخت", allowSensitive = true) == null)
    checkCase("opt-in keeps system secret", NotificationPrivacy.reason(true, "chat", "msg", "Hi", "567890", true, true) == "system_secret")
    checkCase("opt-in keeps previews off", NotificationPrivacy.reason(false, "chat", "msg", "Hi", "567890", allowSensitive = true) == "previews_off")
    println("Android companion privacy: $passed checks PASS")
}
